import Foundation

/// The app icon, as the `icons` entry of `serverInfo` in `initialize` (MCP 2025-11-25), so a
/// client that draws server icons shows the Worklens mark instead of a letter badge.
///
/// Inlined as a `data:` URI rather than read from the bundle: `worklens mcp` also runs from a bare
/// `swift run` binary with no `Resources/`, and a client should not have to fetch anything. It is
/// `Resources/AppIcon.iconset/icon_32x32@2x.png` byte for byte; `MCPServerIconTests` fails when
/// the two drift. To regenerate after an icon change:
///
///     base64 -i "Resources/AppIcon.iconset/icon_32x32@2x.png" | tr -d '\n'
enum MCPServerIcon {
    static let size = "64x64"
    static let mimeType = "image/png"
    static let base64 =
        ""

    static var dataURI: String { "data:\(mimeType);base64,\(base64)" }

    /// The `icons` array as the spec shapes it: `src`, `mimeType`, `sizes`.
    static var iconsJSON: JSONValue {
        .array([
            .object([
                "src": .string(dataURI),
                "mimeType": .string(mimeType),
                "sizes": .array([.string(size)]),
            ])
        ])
    }
}
